const buttons=[...document.querySelectorAll('[data-view]')],views=[...document.querySelectorAll('.portal-view')],toast=document.querySelector('.portal-toast');const notify=m=>{toast.textContent=m;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)};function showView(n){views.forEach(v=>v.classList.toggle('active',v.id===`view-${n}`));document.querySelectorAll('.portal-side [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===n));document.querySelector('.crumb b').textContent=n[0].toUpperCase()+n.slice(1);scrollTo({top:0,behavior:'smooth'})}buttons.forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));document.querySelectorAll('.type-tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.type-tabs button').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('.a-core').textContent=b.dataset.kind==='agent'?'AI agent':'Automation flow'}));document.querySelector('.generate-build').onclick=()=>{document.querySelector('.a-trigger').textContent=document.querySelector('#buildTrigger').value;document.querySelector('.a-review').textContent=document.querySelector('#buildApproval').value;document.querySelector('.build-status').textContent='Generated';document.querySelector('#portalPrompt').textContent=`You are ${document.querySelector('#buildName').value}.\n\nOBJECTIVE\n${document.querySelector('#buildGoal').value}\n\nAPPROVAL\n${document.querySelector('#buildApproval').value}. Record provenance, expose uncertainty, and stop when context is missing.`;notify('Architecture generated')};document.querySelector('.copy-build').onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#portalPrompt').textContent)}catch{}notify('System prompt copied')};document.querySelector('.save-build').onclick=()=>notify('Draft system saved');document.querySelectorAll('.tool-list button').forEach(b=>b.onclick=()=>b.classList.toggle('active'));document.querySelectorAll('.choice').forEach(b=>b.onclick=()=>document.querySelectorAll('.choice').forEach(x=>x.classList.toggle('selected',x===b)));document.querySelector('.approve-decision').onclick=()=>{notify('Direction approved');setTimeout(()=>showView('overview'),500)};document.querySelector('.request-change').onclick=()=>notify('Change request opened');const drawer=document.querySelector('.context-drawer');document.querySelectorAll('.evidence-open').forEach(b=>b.onclick=()=>drawer.classList.add('open'));document.querySelector('.context-close').onclick=()=>drawer.classList.remove('open');document.querySelectorAll('.system-config').forEach(b=>b.onclick=()=>showView('build'));document.addEventListener('keydown',e=>{if(e.key==='Escape')drawer.classList.remove('open')});
